package dev.gamersclt.batcaverna.nativeapp;
import android.app.Activity;import android.graphics.*;import android.view.View;import org.junit.Test;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35,manifest=Config.NONE)
public class ChatImageTest {
 @Test public void imageSelectionChangesSendIdentity(){ChatSendAttempt attempt=new ChatSendAttempt();String id=attempt.begin("alice","private:bob","Legenda","image-one");assertEquals(id,attempt.begin("alice","private:bob","Legenda","image-one"));assertNotEquals(id,attempt.begin("alice","private:bob","Legenda","image-two"));String second=attempt.begin("alice","private:bob","Legenda","image-two");assertNotEquals(second,attempt.begin("alice","private:bob","Outra legenda","image-two"));}
 @Test public void zoomFitsBoundsAndResets(){Activity activity=Robolectric.buildActivity(Activity.class).setup().get();ChatZoomImage image=new ChatZoomImage(activity);image.measure(View.MeasureSpec.makeMeasureSpec(400,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(300,View.MeasureSpec.EXACTLY));image.layout(0,0,400,300);Bitmap bitmap=Bitmap.createBitmap(800,600,Bitmap.Config.ARGB_8888);image.setImageBitmap(bitmap);assertEquals(1,image.zoom(),0);float[] values=new float[9];image.getImageMatrix().getValues(values);assertEquals(.5f,values[Matrix.MSCALE_X],.001f);image.zoomBy(100);assertEquals(5,image.zoom(),0);image.zoomBy(.0001f);assertEquals(1,image.zoom(),0);image.zoomBy(2);image.reset();assertEquals(1,image.zoom(),0);image.getImageMatrix().getValues(values);assertEquals(0,values[Matrix.MTRANS_X],.001f);assertEquals(0,values[Matrix.MTRANS_Y],.001f);bitmap.recycle();activity.finish();}
 @Test public void clearingSelectionRemovesItsUploadPath(){Activity activity=Robolectric.buildActivity(Activity.class).setup().get();ChatImageDraft draft=new ChatImageDraft(activity);draft.uploaded("alice/image.png");draft.clear();assertFalse(draft.selected());assertEquals("",draft.path());assertEquals(View.GONE,draft.getVisibility());activity.finish();}
}
